export type Product = {
  id: string
  name: string
  price: number
  inventory: number
  updatedAt: number
}

const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

const SEED: Product[] = [
  { id: 'SKU-1001', name: 'Acme Wireless Headphones', price: 129.99, inventory: 240, updatedAt: 1_700_000_000_000 },
  { id: 'SKU-1002', name: 'Acme USB-C Hub 7-in-1', price: 49.0, inventory: 1320, updatedAt: 1_700_000_000_000 },
  { id: 'SKU-1003', name: 'Acme Mechanical Keyboard', price: 89.5, inventory: 88, updatedAt: 1_700_000_000_000 },
  { id: 'SKU-1004', name: 'Acme 27" 4K Monitor', price: 329.0, inventory: 47, updatedAt: 1_700_000_000_000 },
  { id: 'SKU-1005', name: 'Acme Aluminium Laptop Stand', price: 35.0, inventory: 610, updatedAt: 1_700_000_000_000 },
  { id: 'SKU-1006', name: 'Acme Bluetooth Speaker', price: 59.99, inventory: 305, updatedAt: 1_700_000_000_000 },
]

let catalog: Product[] = SEED.map((product) => ({ ...product }))

export async function fetchProductsFromDB(): Promise<Product[]> {
  await wait(100)
  return catalog.map((product) => ({ ...product }))
}

export async function syncCatalogFromERP(): Promise<{ synced: number }> {
  await wait(4000)
  const upstream = await fetchERPCatalog()
  catalog = upstream
  return { synced: upstream.length }
}

async function fetchERPCatalog(): Promise<Product[]> {
  await wait(300)
  const updatedAt = Date.now()
  return catalog.map((product) => ({
    ...product,
    price: Math.round(product.price * (0.98 + Math.random() * 0.04) * 100) / 100,
    inventory: Math.max(0, product.inventory + Math.floor(Math.random() * 60 - 25)),
    updatedAt,
  }))
}

import { unstable_cache } from 'next/cache'
import { fetchProductsFromDB, type Product } from './db'

export type { Product }

export const getProducts = unstable_cache(
  async (): Promise<Product[]> => fetchProductsFromDB(),
  ['products'],
  { tags: ['products'] }
)

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  background: #f6f7f9;
  color: #1f2328;
}

a {
  color: #0969da;
}

.catalog {
  max-width: 980px;
  margin: 0 auto;
  padding: 32px 24px;
}

.catalog__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 24px;
}

.catalog__header h1 {
  margin: 0 0 4px;
  font-size: 24px;
}

.catalog__meta {
  margin: 0;
  color: #57606a;
  font-size: 14px;
}

.catalog__header button {
  appearance: none;
  border: 1px solid #1f2328;
  background: #1f2328;
  color: #fff;
  padding: 8px 16px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

.catalog__header button:hover {
  background: #30363d;
}

.catalog__table {
  width: 100%;
  border-collapse: collapse;
  background: #fff;
  border: 1px solid #d0d7de;
  border-radius: 8px;
  overflow: hidden;
  font-size: 14px;
}

.catalog__table th,
.catalog__table td {
  padding: 10px 14px;
  text-align: left;
  border-bottom: 1px solid #eaeef2;
}

.catalog__table thead th {
  background: #f6f8fa;
  font-weight: 600;
  color: #57606a;
}

.catalog__table tbody tr:last-child td {
  border-bottom: none;
}

.catalog__table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

