export type Product = {
  id: string
  name: string
  price: number
  inventory: number
  updatedAt: number
}

const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

const CATALOG: Product[] = [
  { id: 'SKU-1001', name: 'Acme Wireless Headphones', price: 129.99, inventory: 240, updatedAt: 0 },
  { id: 'SKU-1002', name: 'Acme USB-C Hub 7-in-1', price: 49.0, inventory: 1320, updatedAt: 0 },
  { id: 'SKU-1003', name: 'Acme Mechanical Keyboard', price: 89.5, inventory: 88, updatedAt: 0 },
  { id: 'SKU-1004', name: 'Acme 27" 4K Monitor', price: 329.0, inventory: 47, updatedAt: 0 },
  { id: 'SKU-1005', name: 'Acme Aluminium Laptop Stand', price: 35.0, inventory: 610, updatedAt: 0 },
  { id: 'SKU-1006', name: 'Acme Bluetooth Speaker', price: 59.99, inventory: 305, updatedAt: 0 },
]

export async function fetchCatalogFromUpstream(): Promise<Product[]> {
  await wait(1500)
  const updatedAt = Date.now()
  const drift = Math.floor(updatedAt / 1000)
  return CATALOG.map((product) => ({
    ...product,
    price: Math.round(product.price * (1 + (drift % 50) / 1000) * 100) / 100,
    inventory: Math.max(0, product.inventory + (drift % 30)),
    updatedAt,
  }))
}

import { unstable_cache } from 'next/cache'
import { fetchCatalogFromUpstream, type Product } from './db'

export type { Product }

export const getProducts = unstable_cache(
  async (): Promise<Product[]> => fetchCatalogFromUpstream(),
  ['products'],
  { tags: ['products'] }
)

